+                            <div class="task-assignee">@task.Assignee</div>
+                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
+                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
+                            <div class="task-actions">
+                                @if (columnIndex > 0)
+                                {
+                                    var leftStatus = _columns[columnIndex - 1];
+                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => MoveTask(task.Id, leftStatus)">Move Left</button>
+                                }
+                                @if (columnIndex < _columns.Length - 1)
+                                {
+                                    var rightStatus = _columns[columnIndex + 1];
+                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => MoveTask(task.Id, rightStatus)">Move Right</button>
